files.content:
* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #1e293b, #334155);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: #f8fafc;
  padding: 16px;
}

.card {
  background: #0f172a;
  border-radius: 16px;
  padding: clamp(16px, 4vw, 32px);
  width: 100%;
  max-width: 480px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  margin: 0 0 8px;
  font-size: clamp(1.4rem, 4vw, 1.8rem);
  color: #e2e8f0;
}

.subtitle {
  margin: 0 0 16px;
  color: #94a3b8;
  font-size: 1rem;
}

.stats {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 16px;
  margin-bottom: 16px;
  font-size: 1.1rem;
}

.solved {
  color: #4ade80;
  font-weight: 700;
  font-size: 1.2rem;
}

.grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  aspect-ratio: 1 / 1;
  margin: 0 auto 20px;
  width: 100%;
  max-width: 400px;
}

.tile {
  border: 3px solid transparent;
  border-radius: 10px;
  cursor: pointer;
  transition: transform 0.1s, border-color 0.1s, box-shadow 0.1s;
  padding: 0;
  min-width: 0;
  min-height: 0;
  font-size: 0;
}

.tile:hover {
  transform: scale(1.05);
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.3);
}

.tile:focus-visible {
  outline: none;
  border-color: #fbbf24;
  box-shadow: 0 0 0 4px rgba(251, 191, 36, 0.5);
}

.tile.selected {
  border-color: #fbbf24;
  box-shadow: 0 0 0 4px rgba(251, 191, 36, 0.5);
  transform: scale(1.05);
}

.tile:active {
  transform: scale(0.95);
}

button#shuffleBtn {
  background: #3b82f6;
  color: #fff;
  border: none;
  border-radius: 10px;
  padding: 12px 32px;
  font-size: 1.1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  font-family: inherit;
}

button#shuffleBtn:hover {
  background: #2563eb;
}

button#shuffleBtn:focus-visible {
  outline: 3px solid #fbbf24;
  outline-offset: 2px;
}

button#shuffleBtn:active {
  transform: scale(0.97);
}

.hint {
  margin: 16px 0 0;
  font-size: 0.9rem;
  color: #64748b;
  line-height: 1.4;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  .grid {
    gap: 6px;
  }
  .stats {
    font-size: 1rem;
  }
}

const COLORS = ['#ef4444', '#3b82f6', '#22c55e', '#eab308'];
const SIZE = 4;

const gridEl = document.getElementById('grid');
const swapCountEl = document.getElementById('swapCount');
const solvedMessageEl = document.getElementById('solvedMessage');
const shuffleBtn = document.getElementById('shuffleBtn');

let grid = [];
let selected = null;
let swaps = 0;

function createSolvedGrid() {
  return COLORS.flatMap(color => Array(SIZE).fill(color));
}

function shuffleArray(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function isSolved() {
  for (let r = 0; r < SIZE; r++) {
    const first = grid[r * SIZE];
    for (let c = 1; c < SIZE; c++) {
      if (grid[r * SIZE + c] !== first) return false;
    }
  }
  return true;
}

function newPuzzle() {
  do {
    grid = shuffleArray(createSolvedGrid());
  } while (isSolved());
  selected = null;
  swaps = 0;
  render();
}

function render() {
  gridEl.innerHTML = '';
  grid.forEach((color, i) => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'tile';
    btn.style.background = color;
    btn.dataset.index = i;
    btn.setAttribute('aria-label', `Row ${Math.floor(i / SIZE) + 1}, Column ${(i % SIZE) + 1}, color ${colorName(color)}`);
    btn.setAttribute('aria-pressed', selected === i ? 'true' : 'false');
    if (selected === i) btn.classList.add('selected');
    btn.addEventListener('click', onTileClick);
    gridEl.appendChild(btn);
  });
  swapCountEl.textContent = swaps;
  solvedMessageEl.hidden = !isSolved();
}

function colorName(hex) {
  const map = { '#ef4444': 'red', '#3b82f6': 'blue', '#22c55e': 'green', '#eab308': 'yellow' };
  return map[hex] || 'unknown';
}

function areAdjacent(a, b) {
  const ra = Math.floor(a / SIZE), ca = a % SIZE;
  const rb = Math.floor(b / SIZE), cb = b % SIZE;
  return Math.abs(ra - rb) + Math.abs(ca - cb) === 1;
}

function onTileClick(e) {
  const index = Number(e.currentTarget.dataset.index);
  if (selected === null) {
    selected = index;
    render();
    return;
  }
  if (selected === index) {
    selected = null;
    render();
    return;
  }
  if (areAdjacent(selected, index)) {
    [grid[selected], grid[index]] = [grid[index], grid[selected]];
    swaps++;
    selected = null;
    render();
  } else {
    selected = index;
    render();
  }
}

shuffleBtn.addEventListener('click', newPuzzle);

newPuzzle();
